SELECT id, name, email, country, city, segment, signup_date, is_active, credit_limit, age, SUM(credit_limit) OVER (PARTITION BY city ORDER BY credit_limit, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) running_credit_limit, RANK() OVER (PARTITION BY segment ORDER BY credit_limit) credit_limit_rank, LAST_VALUE(segment, TRUE) OVER (ORDER BY credit_limit, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) last_known_segment, COUNT(credit_limit) OVER (PARTITION BY segment) segment_count_credit_limit FROM customers;
